import * as Runtime from "@sdk/runtime";

const lib = Runtime.runtime({ baseUrl: "/api" });

export type UserDto = { id: string; name: string };

export function getMyUser(opts?: Runtime.RequestOpts) {
  return lib.ok(lib.fetchJson<{ status: 200; data: UserDto }>("/users/me", { ...opts }));
}

export function updateMyUser(dto: UserDto, opts?: Runtime.RequestOpts) {
  return lib.ok(lib.fetchJson("/users/me", { ...opts, method: "PUT", body: dto }));
}

export function deleteActivity(id: string, opts?: Runtime.RequestOpts) {
  return lib.ok(
    lib.fetchText(`/activities/${encodeURIComponent(id)}`, lib.json({ ...opts, method: "DELETE" })),
  );
}
